double stop_ratio = 0;
int run_mode = 0;
double limit_s = 0;

if (run_mode == 3) {  
  printf("mode=3 num_iter=%u stop_ratio=%g limit_s=%g\n", num_iter, stop_ratio, limit_s);
  double iter_s = 0;  
  for (unsigned t = 1; t <= num_iter; ++t) {
    double a = omp_get_wtime();
    CDF_CliqueEnum(g, k, FRANK_WOLFE);
    double b = omp_get_wtime();
    iter_s += b - a;
    for (unsigned i = 0; i < g->n; ++i)
      rho_tentative[i] = 0;
    DensestSubsetInfo info = CDF_FindDensestSubset(g, k, t);
    double report_s = omp_get_wtime() - b;
    clock_t t1 = clock();
    int cert = stop_ratio > 0 && info.density > 0 && info.ub <= stop_ratio * info.density;
    printf("iteration %u: Approximate densest subgraph: %u nodes, %u edges, edge density = %f, k-clique density = %f, upper bound = %f. %ld milliseconds. iterations_ms = %.1f report_ms = %.1f%s\n", t, info.n, info.m, info.m * 2.0 / info.n / (info.n - 1), info.density, info.ub, (t1 - t0) * 1000 / CLOCKS_PER_SEC, iter_s * 1000, report_s * 1000, cert ? " certified" : "");
    fflush(stdout);
    if (cert)
      break;
    if (limit_s > 0 && iter_s + report_s > limit_s) {
      printf("limit reached: iterations plus report over %g s\n", limit_s);
      break;
    }
  }
  return;
}

if (argc > 6) stop_ratio = atof(argv[6]);  
if (argc > 7) run_mode = atoi(argv[7]);    
if (argc > 8) limit_s = atof(argv[8]);
